pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(c).balance);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        c.sendTo(address(0xdead), amount);
        uint256 balAfter = address(c).balance;
        // The reference (and the buggy) always transfer `amount` if the call succeeds.
        // The difference is *who* is allowed: the buggy one allows any caller, causing a balance drop for any `caller`;
        // the reference would revert for non-owner and leave the balance unchanged.
        // Thus, a universal property: if the call did NOT revert (and we know it doesn't for the buggy version),
        // the balance after is exactly balBefore - amount.
        // But this holds for both! We need a property that the reference satisfies and the bug breaks.
        // The correct invariant: after a non-owner calls sendTo, the balance remains UNCHANGED (because it reverts).
        // The bug breaks this: a non-owner call succeeds and changes the balance.
        // We detect revert via try/catch.
        bool ok;
        vm.prank(caller);
        try c.sendTo(address(0xdead), amount) { ok = true; } catch { ok = false; }
        if (caller != c.owner()) {
            assertTrue(!ok); // must revert for non-owner
        }
    }
}

