pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address receiver, uint256 amount) public {
        // 1. admissible domain: sender must differ from the known owner, because the owner check is the heart of the difference.
        //    We restrict to exactly one class: non-owner callers.
        address owner = address(uint160(uint256(vm.load(address(c), bytes32(uint256(0)))))); // owner is at storage slot 0
        vm.assume(sender != owner);
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(0));
        // bound amount to avoid overflow and unrealistic values, keep it wide
        amount = bound(amount, 0, address(c).balance);

        // 2. give c enough ether to transfer
        vm.deal(address(c), amount + 1);
        vm.deal(sender, 1);

        // 3. capture revert behaviour by a low-level call from a *non-owner*
        vm.prank(sender);
        (bool ok_ref, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // The invariant: for every non-owner sender, the call reverts (returns false)
        assertTrue(!ok_ref);

        // The mutant with require(false) also reverts, but the test deliberately focuses on the reference only:
        // the reference passes because the non-owner check correctly triggers revert,
        // the mutant also passes this test, so we need a DIFFERENT invariant.
        // WAIT — the instruction says the test must PASS on reference for ALL inputs and FAIL on buggy for SOME input.
        // If I assert "non-owner always reverts", the buggy ALSO reverts (require(false) always reverts) → the buggy passes too → REJECTED (doesn't distinguish).
        // Thus we must choose the complementary case: OWNER call MUST NOT revert.
        // Adversarial environment is NOT needed here — the call success/failure depends purely on sender.
        // We'll fuzz amount, receiver, but fix sender to owner to test non-revert for owner.
        // However, the fuzzer MUST fuzz the deciding values (sender). We'll fuzz sender but use vm.assume to partition the input space into two calls, then assert the real difference.
        // Actually, the simplest correct choice: assert that sendTo reverts if and only if sender != owner.
        // This is a universal rule: for any sender, sender != owner => revert, sender == owner => no revert.
        // The reference satisfies it for all inputs; the bug violates it for owner (reverts incorrectly).
        // We can test it with a single fuzz round by making TWO calls and combining.
        // Since the test must contain exactly one assertTrue, we must encode both outcomes into one boolean.
        // Strategy: pick a fixed receiver, fuzz sender and amount. Call from sender.
        // If sender == owner: record success; else: record revert. Then assertTrue( (sender==owner) ? success : !success ).
        // But that uses if/else — allowed.
        // Even better: use try/catch to get a success flag for ANY sender.
        // Then assertTrue( (sender == owner) == success ).
        // That satisfies both: reference: for any sender, condition holds; bug: for owner, success=false, condition false → assert fails.
        // This is fully fuzzed over sender, receiver, amount.
        // No helper needed.

        // We must still respect the check that already failed in the original run (test failed on reference).
        // The failure reason: the original test likely asserted "always revert for non-owner" and some input didn't revert because the reference reverted only for non-owner, but wait...
        // The error message says the fuzz test already FAILS on reference before any bug, with a counterexample args: 0x2Db27aFeD079191a849683029cF095E79DF9Adc0, 340422364691424053057726273.
        // That is a specific sender and huge amount. Probably the test enforced a too-strict rule (like "always revert") and found an input where it doesn't revert?
        // Actually the counterexample has a huge amount; perhaps the assertion was about balances after a non-owner call, and the transfer still succeeded because require(msg.sender == owner) reverted, but the test expected something else.
        // The point: we must tighten the rule so the reference holds for every admissible input.
        // The rule "sender==owner iff success" is perfect and holds for reference (given enough ether in c).
        // We must ensure c has enough ether for the transfer when owner calls, else transfer fails due to insufficient balance, breaking the "owner => success" part.
        // So we must precondition: if sender==owner, c must have at least amount balance. We'll only assert the rule under that precondition.
        // To keep it simple and fuzzable, we can vm.deal(address(c), amount) before each call, so it always has enough.
        // But if sender != owner, the call reverts early anyway, and c's balance doesn't matter.
        // So we can fund c appropriately.
    }
}

