contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        // Bound amount to avoid overflow and make assertions meaningful
        amount = bound(amount, 1, 100 ether);

        // Owner sends via sendTo; the reference should succeed and transfer funds.
        // Buggy version will always revert, so balance of receiver will never change.
        uint256 balBefore = receiver.balance;
        address owner = address(this); // In setUp, c's owner is this test contract

        vm.prank(owner);
        bool ok = true;
        try c.sendTo(receiver, amount) {
        } catch {
            ok = false;
        }

        uint256 balAfter = receiver.balance;

        // Property: If the call did not revert, receiver balance must have increased by amount.
        // For the reference, ok==true and balance increases; for buggy, ok==false always, so the implication holds vacuously.
        // But to catch the bug, we assert the stronger statement: ok must be true (i.e., it must not revert) => balance increased.
        // Since the bug always reverts, ok is always false, making the implication true, which is NOT a failure.
        // We need a property the reference satisfies (ok==true -> balance increased) AND the bug breaks.
        // The bug breaks the statement "ok is true and balance increased" because ok is never true.
        // So the actual distinguishing property: ok == true (call succeeded) AND balance increased.
        // Reference: ok true, balance increased. Bug: ok false, so assertion fails.
        assertTrue(ok && balAfter == balBefore + amount);
    }
}

