import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict amount to something the owner can actually send based on balance funded below.
        // Keep domain wide: bound amount to a large range that is fundable.
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(this));
        vm.assume(receiver != address(c));
        amount = bound(amount, 0, 1 ether);

        // Setup: fund the owner (which is this test contract initially because constructor sets owner=msg.sender in setUp)
        address owner = address(this);
        vm.deal(owner, amount);

        // Record receiver's balance before the call
        uint256 balBeforeReceiver = receiver.balance;

        // Owner calls sendTo
        c.sendTo(receiver, amount);

        // After the call, the receiver's balance must have increased by exactly amount.
        uint256 balAfterReceiver = receiver.balance;
        assertTrue(balAfterReceiver == balBeforeReceiver + amount);
    }
}

