pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict to admissible domain: sender must be owner, amount <= balance to avoid revert on transfer
        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner")))));
        vm.assume(receiver != address(c) && receiver != address(0));
        vm.deal(address(c), amount);
        vm.deal(owner, 1 ether);

        uint256 balanceBefore = address(c).balance;
        vm.prank(owner);
        c.sendTo(receiver, amount);

        // The invariant: contract balance must decrease by exactly amount sent
        assertEq(address(c).balance, balanceBefore - amount);
    }
}

