pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        // The constructor sets owner = msg.sender (this test contract).
        owner = address(this);
    }

    function testFuzz_property(address receiver, uint256 amount) public {
        // Keep amount in an admissible, non-zero range that does not overflow.
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance / 2);
        // receiver must be different from owner to avoid trivial self-transfer issues,
        // and must be a payable address that can receive ETH.
        vm.assume(receiver != owner);
        vm.assume(receiver != address(0));
        // Ensure receiver has no code (EOA) so call/transfer succeeds.
        vm.assume(receiver.code.length == 0);

        uint256 balBefore = address(c).balance;
        vm.deal(owner, amount);
        vm.prank(owner);
        c.sendTo(receiver, amount);
        uint256 balAfter = address(c).balance;

        // Reference property: contract balance must decrease by exactly the amount sent.
        // The buggy version does not forward value, so the balance remains unchanged
        // – assertion fails whenever amount > 0.
        assertTrue(balBefore - balAfter == amount);
    }
}

