pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict the receiver to a valid address and amount to contract balance
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, address(c).balance);

        // Fund the contract to enable a successful transfer
        vm.deal(address(c), amount);

        // Record the contract's balance before sendTo
        uint256 balanceBefore = address(c).balance;

        // The owner (this test contract) calls sendTo to send the amount
        c.sendTo(receiver, amount);

        // The reference C.transfer() forwards the value, so contract balance must decrease by amount.
        // The buggy M.call("") does NOT forward value, so the contract balance stays the same.
        // The property: after sendTo, the contract balance is strictly less than before.
        // This holds for EVERY admissible input on the reference, but fails on the buggy version
        // for any input when the fuzzer picks a valid amount > 0.
        assertTrue(address(c).balance < balanceBefore);
    }
}

